package com.warehouse.web; import com.warehouse.domain.*; import com.warehouse.repo.*; import com.opencsv.*; import com.lowagie.text.*; import com.lowagie.text.pdf.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.io.*;
@RestController @RequestMapping("/api/v1/reports") @PreAuthorize("hasRole('ADMIN')") public class ReportController { final ItemRepository items; final TransactionRepository txs; public ReportController(ItemRepository i,TransactionRepository t){items=i;txs=t;} @GetMapping(value="/items.csv",produces="text/csv") public ResponseEntity<byte[]> csv() throws IOException {var out=new StringWriter();try(var csv=new CSVWriter(out)){csv.writeNext(new String[]{"Name","SKU","Barcode","Quantity","Threshold"});for(Item i:items.findAll())csv.writeNext(new String[]{i.name,i.sku,i.barcode,String.valueOf(i.quantity),String.valueOf(i.lowStockThreshold)});}return download(out.toString().getBytes(),"items.csv","text/csv");} @GetMapping(value="/items.pdf",produces="application/pdf") public ResponseEntity<byte[]> pdf() throws Exception {var out=new ByteArrayOutputStream();var doc=new Document();PdfWriter.getInstance(doc,out);doc.open();doc.add(new Paragraph("Warehouse inventory report",FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));for(Item i:items.findAll())doc.add(new Paragraph(i.sku+"  |  "+i.name+"  |  "+i.quantity+" "+i.unit));doc.close();return download(out.toByteArray(),"items.pdf","application/pdf");} private ResponseEntity<byte[]> download(byte[] b,String n,String type){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+n).contentType(MediaType.parseMediaType(type)).body(b);} }
